mapper:

        SELECT *
        FROM {{table_name}}

{{#each query_fields}}

                AND {{column_name}} {{operator}} #{queryForm.{{field_name}}}

{{/each}}
{{#if has_deleted_flag}}

                AND deleted_flag = #{queryForm.deletedFlag}

{{/if}}

        ORDER BY {{default_order_column}} DESC


{{#if has_unique_field}}

        SELECT *
        FROM {{table_name}}
        WHERE {{unique_column_name}} = #{{{unique_field_name}}}
{{#if has_deleted_flag}}
          AND deleted_flag = false
{{/if}}


{{/if}}
{{#if has_deleted_flag}}

        UPDATE {{table_name}}
        SET deleted_flag = true,
            update_time = NOW()
        WHERE {{id_column_name}} = #{{{id_field_name}}}


{{/if}}
